// Voice clips for the Shorts (WO-028): VOICEVOX 春日部つむぎ, generated by tools/make_voice.py into
// apps/shorts/public/voice/<cardId>/<key>.m4a with their text and length in manifest.json. A clip plays
// only while its text still matches the Short's line; a missing or stale clip means a silent line.
import manifest from '../public/voice/manifest.json';

interface Clip {
  text: string;
  file: string;
  ms: number;
}

const clips = manifest as unknown as Record<string, Record<string, Clip>>;

/** Length of the clip for a line, when one was generated for exactly this text (undefined otherwise). */
export function voiceMs(cardId: string, key: string, speech: string): number | undefined {
  const clip = clips[cardId]?.[key];
  return clip && clip.text === speech ? clip.ms : undefined;
}

/** Path under public/ for staticFile(), or null when the line has no up-to-date clip (it plays silent). */
export function voiceClip(cardId: string, key: string, speech: string): string | null {
  const clip = clips[cardId]?.[key];
  return clip && clip.text === speech ? `voice/${cardId}/${clip.file}` : null;
}

/** The voice timing function for a card's plan. */
export const voiceFor = (cardId: string) => (key: string, speech: string) => voiceMs(cardId, key, speech);
